const uint8_t *font8x16_glyph(uint16_t cp)
{
    size_t lo = 0, hi = sizeof(s_glyphs) / sizeof(s_glyphs[0]);
    while (lo < hi)
    {
        size_t mid = (lo + hi) / 2;
        if (s_glyphs[mid].cp == cp)
            return s_glyphs[mid].rows;
        if (s_glyphs[mid].cp < cp)
            lo = mid + 1;
        else
            hi = mid;
    }
    return NULL;
}
